import{_ as t,o,c as d,a2 as a}from"./chunks/framework.il0noOp3.js";const m=JSON.parse('{"title":"Parameters Reference","description":"Complete reference of all Invoke-AzureScout and Test-AZSCPermissions parameters.","frontmatter":{"description":"Complete reference of all Invoke-AzureScout and Test-AZSCPermissions parameters."},"headers":[],"relativePath":"guide/parameters.md","filePath":"guide/parameters.md"}'),r={name:"guide/parameters.md"};function s(n,e,i,c,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="parameters-reference" tabindex="-1">Parameters Reference <a class="header-anchor" href="#parameters-reference" aria-label="Permalink to &quot;Parameters Reference&quot;">​</a></h1><h2 id="invoke-azurescout-parameters" tabindex="-1">Invoke-AzureScout Parameters <a class="header-anchor" href="#invoke-azurescout-parameters" aria-label="Permalink to &quot;Invoke-AzureScout Parameters&quot;">​</a></h2><h3 id="core" tabindex="-1">Core <a class="header-anchor" href="#core" aria-label="Permalink to &quot;Core&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>-TenantID</code></td><td>Target Azure AD / Entra ID tenant ID</td></tr><tr><td><code>-SubscriptionID</code></td><td>Limit to one or more specific subscription IDs (comma-separated or array)</td></tr><tr><td><code>-ResourceGroup</code></td><td>Limit to one or more specific resource groups</td></tr><tr><td><code>-ManagementGroup</code></td><td>Inventory all subscriptions under a management group</td></tr><tr><td><code>-Scope</code></td><td><code>ArmOnly</code> (default), <code>All</code>, or <code>EntraOnly</code> — controls which data domains are inventoried</td></tr><tr><td><code>-OutputFormat</code></td><td>Global output contract for every run mode: <code>React</code>, <code>Json</code>, <code>JsonEvidence</code>, or <code>All</code> (default, selects all three). Accepts an array. Legacy names still bind for compatibility but are on hold and are not emitted. See <a href="./../assessment/configuration.html#report-tiers">Report tiers</a>.</td></tr><tr><td><code>-Assessment</code></td><td>Switches the run to <strong>assessment mode</strong> — see <a href="#assessment-mode-parameters">Assessment-mode Parameters</a>. Omit for an inventory run</td></tr><tr><td><code>-NoWizard</code></td><td>Skip the guided wizard that a bare, interactive <code>Invoke-AzureScout</code> opens, and run the default inventory instead. Alias: <code>-NonInteractive</code>. Never needed in CI — the wizard already suppresses itself in non-interactive hosts</td></tr><tr><td><code>-NoProgress</code></td><td>Suppress interactive progress rendering. Scout already chooses log-friendly output automatically in CI, redirected, and non-interactive hosts</td></tr><tr><td><code>-Category</code></td><td>Filter by resource category: <code>AI</code>, <code>Analytics</code>, <code>Compute</code>, <code>Containers</code>, <code>Databases</code>, <code>Hybrid</code>, <code>Identity</code>, <code>Integration</code>, <code>IoT</code>, <code>Management</code>, <code>Monitor</code>, <code>Networking</code>, <code>Security</code>, <code>Storage</code>, <code>Web</code> — see <a href="./category-filtering.html">Category Filtering</a></td></tr></tbody></table><h3 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>-AppId</code></td><td>Service principal application (client) ID</td></tr><tr><td><code>-Secret</code></td><td>Service principal client secret or certificate password</td></tr><tr><td><code>-CertificatePath</code></td><td>Path to <code>.pfx</code> certificate file for SPN authentication</td></tr><tr><td><code>-DeviceLogin</code></td><td>Use device code authentication flow (for headless/remote sessions)</td></tr></tbody></table><p>See <a href="./authentication.html">Authentication</a> for detailed examples of each method.</p><h3 id="content-options" tabindex="-1">Content Options <a class="header-anchor" href="#content-options" aria-label="Permalink to &quot;Content Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>-SecurityCenter</code></td><td>Include Microsoft Defender for Cloud data (assessments, alerts, secure score)</td></tr><tr><td><code>-IncludeTags</code></td><td>Include resource tags in Excel worksheets</td></tr><tr><td><code>-SkipPolicy</code></td><td>Skip Azure Policy compliance collection</td></tr><tr><td><code>-SkipAdvisory</code></td><td>Skip Azure Advisor recommendation collection</td></tr><tr><td><code>-SkipVMDetails</code></td><td>Skip extra VM detail collection (extensions, boot diagnostics status)</td></tr><tr><td><code>-SkipDiagram</code></td><td>Skip network diagram generation</td></tr><tr><td><code>-SkipPermissionCheck</code></td><td>Skip the pre-flight permission validation</td></tr><tr><td><code>-PermissionAudit</code></td><td>Standalone permission audit — connects, checks ARM/RBAC (and Graph, with <code>-IncludeEntraPermissions</code>) then exits without collecting. Aliases: <code>-AuditPermissions</code>, <code>-CheckPermissions</code>. Prints an overall readiness verdict plus a per-collector impact table naming every collector a missing permission will leave empty and which permission fixes it — the verdict word alone used to be the only answer, which could read READY over worksheets that were about to come back empty</td></tr><tr><td><code>-IncludeEntraPermissions</code></td><td>With <code>-PermissionAudit</code>, also audit Microsoft Graph / Entra ID access. Alias: <code>-EntraAudit</code></td></tr></tbody></table><h3 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>-ReportName</code></td><td>Custom report filename (default: <code>AzureScout_Report_&lt;timestamp&gt;</code>)</td></tr><tr><td><code>-ReportDir</code></td><td>Base output directory (default: <code>C:\\AzureScout\\</code> on Windows, <code>$HOME/AzureScout/</code> on Linux/Mac)</td></tr><tr><td><code>-RunName</code></td><td>Friendly name for this run&#39;s output folder instead of the generated timestamp, e.g. <code>-RunName &#39;Production-TenantA&#39;</code>. Invalid path characters become <code>-</code></td></tr><tr><td><code>-Force</code></td><td>Write directly into <code>-ReportDir</code>, overwriting any previous run in place. Without it, each run gets its own timestamped folder so a rerun cannot destroy the previous run&#39;s cache or report</td></tr><tr><td><code>-Lite</code></td><td>Legacy compatibility switch for the held Excel renderer; it does not change a live React/JSON output</td></tr></tbody></table><h3 id="azure-devops" tabindex="-1">Azure DevOps <a class="header-anchor" href="#azure-devops" aria-label="Permalink to &quot;Azure DevOps&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>-IncludeDevOps</code></td><td>Also inventory Azure DevOps: projects, pipelines, service connections, repositories, agent pools. Adds five worksheets. Aliases: <code>-IncludeADO</code>, <code>-DevOps</code>. See <a href="./../automation-guide/azure-devops.html">Azure DevOps</a></td></tr><tr><td><code>-DevOpsOrganization</code></td><td>Organization name(s) to inventory. Omit to discover them from the signed-in profile — service principals must name them explicitly. Alias: <code>-ADOOrganization</code></td></tr><tr><td><code>-DevOpsPat</code></td><td>Personal access token, used instead of the current Azure sign-in. Needs read scope on Project and Team, Build, Release, Code, Service Connections, Agent Pools. Alias: <code>-ADOPat</code></td></tr></tbody></table><h3 id="unattended-execution" tabindex="-1">Unattended execution <a class="header-anchor" href="#unattended-execution" aria-label="Permalink to &quot;Unattended execution&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>-Automation</code></td><td>Run non-interactively for an Azure Automation Account runbook: no interactive login, ThreadJob instead of background Job, progress to the job output stream. See <a href="./../automation-guide/automation.html">Azure Automation Account</a></td></tr><tr><td><code>-StorageAccount</code></td><td>Storage account to upload the generated reports to. Authenticates to the data plane with the connected identity, so the identity needs <strong>Storage Blob Data Contributor</strong></td></tr><tr><td><code>-StorageContainer</code></td><td>Blob container within <code>-StorageAccount</code> that reports are written to</td></tr></tbody></table><h3 id="diagram" tabindex="-1">Diagram <a class="header-anchor" href="#diagram" aria-label="Permalink to &quot;Diagram&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>-DiagramFullEnvironment</code></td><td>Include all network components in the draw.io topology diagram</td></tr></tbody></table><h3 id="other" tabindex="-1">Other <a class="header-anchor" href="#other" aria-label="Permalink to &quot;Other&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>-AzureEnvironment</code></td><td>Target Azure cloud: <code>AzureCloud</code> (default), <code>AzureUSGovernment</code>, <code>AzureChinaCloud</code>, <code>AzureGermanCloud</code></td></tr><tr><td><code>-Debug</code></td><td>Verbose debug output during extraction and processing</td></tr></tbody></table><h2 id="test-azscpermissions-parameters" tabindex="-1">Test-AZSCPermissions Parameters <a class="header-anchor" href="#test-azscpermissions-parameters" aria-label="Permalink to &quot;Test-AZSCPermissions Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>-TenantID</code></td><td>Target tenant ID to validate permissions against</td></tr><tr><td><code>-Scope</code></td><td><code>All</code> (default), <code>ArmOnly</code>, or <code>EntraOnly</code> — controls which permission checks run</td></tr></tbody></table><p>Returns a structured object:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$result </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Test-AZSCPermissions</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TenantID </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;00000000-...&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Scope All</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$result.ArmAccess    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># $true / $false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$result.GraphAccess  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># $true / $false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$result.Details      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Array of check results with remediation guidance</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>See <a href="./permissions.html">Permissions</a> for the full list of required roles and API permissions.</p><h2 id="assessment-mode-parameters" tabindex="-1">Assessment-mode Parameters <a class="header-anchor" href="#assessment-mode-parameters" aria-label="Permalink to &quot;Assessment-mode Parameters&quot;">​</a></h2><p>Adding <code>-Assessment</code> switches <code>Invoke-AzureScout</code> from inventory to the <strong>CAF/WAF assessment</strong>. All the sign-in and scoping parameters above still apply. Full run-mode examples: <a href="./../assessment/assessment.html#run-modes">Assessment guide</a>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>-Assessment</code></td><td>One, several, or <code>All</code> assessment names from <code>manifests/assessments.psd1</code>. Supplying it is what selects assessment mode; omit it for an inventory run. Alias <code>-Assess</code>. Fifteen of the twenty-four entries score a single inventory category and are named <code>&#39;Assess: &lt;Category&gt;&#39;</code> — e.g. <code>&#39;Assess: Compute&#39;</code>, not <code>Compute</code> — because that name previously collided with the inventory <code>-Category</code> value of the same name. The colon and space mean the value must be quoted. Legacy unprefixed names (<code>Compute</code>, <code>Storage</code>, ...) still resolve, with a warning naming the new value. Those fifteen are a stopgap — they are category-scoped filters over the same CAF/WAF rule set <code>CAF: Azure Landing Zone</code> runs in full, and they are due to be retired once per-pillar assessments exist. See the <a href="./../design/assessment-registry.html">Assessment Registry</a>.</td></tr><tr><td><code>-InventoryAndAssessment</code></td><td>Switch, alias <code>-Both</code>. Runs the inventory pass and the <code>-Assessment</code> pass from <strong>one</strong> collection instead of two — the assessment is handed the inventory&#39;s already-collected rows rather than re-querying Azure. Without it, <code>-Assessment</code> alone returns the assessment only; getting both previously meant invoking the command twice (and collecting from Azure twice) or answering the wizard&#39;s &quot;run both?&quot; prompt, which no script or CI pipeline could reach. See <a href="./overview.html#running-both">Overview: running both</a>.</td></tr><tr><td><code>-Scope</code></td><td><code>ArmOnly</code> or <code>All</code> — both run the ARM/Resource Graph collect. <code>EntraOnly</code> throws, because the assessment Collect layer has no Entra/Graph path; use an inventory run with <code>-Scope EntraOnly</code> for Entra ID.</td></tr><tr><td><code>-Category</code></td><td>Filters which Resource Graph queries the Collect layer runs, narrowing the collect below the assessment&#39;s manifest default.</td></tr><tr><td><code>-OutputFormat</code></td><td>Same global contract as inventory and combined runs: <code>React</code>, <code>Json</code>, <code>JsonEvidence</code>, or <code>All</code> (selects all three). <code>React</code> renders a self-contained multi-page <code>report-react.html</code> — inventory blades, a full conformance register per assessment, diagrams, drift, and a remediation plan — with an Executive/Consultant/Data view-depth toggle, a light/dark theme, and Markdown/JSON/CSV/Print/standalone-HTML exports. <code>JsonEvidence</code> is a resources-only JSON export with no assessment metadata. Every legacy renderer name is on hold. See <a href="./../assessment/configuration.html#report-tiers">Report tiers</a> and <a href="./../reference/react-report-section-contract.html">the section contract</a>.</td></tr><tr><td><code>-ReportDir</code></td><td>Base output directory; each run writes to a dated subfolder.</td></tr><tr><td><code>-PermissionAudit</code></td><td>Switch — runs <code>Test-ScoutPermission</code> for the requested <code>-Assessment</code> set and returns before any collection happens.</td></tr><tr><td><code>-CollectOnly</code></td><td>Switch — stop after Collect; returns the path to <code>collect.json</code>.</td></tr><tr><td><code>-FromCollect</code></td><td>Path to an existing <code>collect.json</code> — skips Collect/Ingest and assesses/reports from it directly. Runs fully offline, so it does <strong>not</strong> trigger a sign-in.</td></tr><tr><td><code>-ManagementGroup</code></td><td>Scopes the Resource Graph <code>Collect</code> layer (and the opt-in <code>AzGovViz</code> ingest, if selected instead of the native <code>Governance</code> default) for assessments that need it (<code>CAF: Azure Landing Zone</code>, <code>Management</code>, <code>Identity</code>, <code>Scout: Governance Baseline</code>, <code>Policy</code>).</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Former assessment command removed</p><p>The standalone assessment command was removed in <strong>v3.0.0</strong>. Use <code>Invoke-AzureScout -Assessment</code> with <code>-ReportDir</code> and <code>-ManagementGroup</code> instead.</p></div><h2 id="invoke-scoutpipeline-parameters" tabindex="-1">Invoke-ScoutPipeline Parameters <a class="header-anchor" href="#invoke-scoutpipeline-parameters" aria-label="Permalink to &quot;Invoke-ScoutPipeline Parameters&quot;">​</a></h2><p>Unattended, one-command wrapper (<code>src/Invoke-ScoutPipeline.ps1</code>, exported) that runs collect → assess → report headless into a single dated run folder. See <a href="./../assessment/assessment.html#unattended-one-command-run-invoke-scoutpipeline">Assessment guide — unattended, one-command run</a>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>-Assessment</code></td><td>Same as <code>Invoke-AzureScout -Assessment</code> — one, several, or <code>All</code>.</td></tr><tr><td><code>-OutputFormat</code></td><td>Same global contract as <code>Invoke-AzureScout</code>: <code>React</code>, <code>Json</code>, <code>JsonEvidence</code>, or <code>All</code> (default, selects all three). Every legacy renderer is on hold.</td></tr><tr><td><code>-OutputPath</code></td><td>Base output directory; each run writes to a dated subfolder.</td></tr><tr><td><code>-ManagementGroupId</code></td><td>Same scoping behaviour as assessment mode’s <code>-ManagementGroup</code>.</td></tr><tr><td><code>-Category</code></td><td>Same as assessment mode’s <code>-Category</code>.</td></tr><tr><td><code>-SkipPermissionAudit</code></td><td>Switch — skips the read-only permission pre-flight that otherwise runs first.</td></tr></tbody></table><p>Returns the run-folder path. Throws and sets <code>$LASTEXITCODE = 1</code> only when <code>pipeline-summary.json</code>&#39;s <code>outcome</code> is <code>Failed</code>; an exporter failure degrades the run to <code>PartialSuccess</code> instead of losing the output that did succeed.</p><h2 id="test-scoutpermission-parameters" tabindex="-1">Test-ScoutPermission Parameters <a class="header-anchor" href="#test-scoutpermission-parameters" aria-label="Permalink to &quot;Test-ScoutPermission Parameters&quot;">​</a></h2><p>Read-only permission pre-flight for the assessment platform — distinct from <code>Test-AZSCPermissions</code> above. Normally invoked via <code>Invoke-AzureScout -Assessment ... -PermissionAudit</code> rather than called directly.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>-Assessment</code></td><td>The assessment name(s) to check permissions for.</td></tr><tr><td><code>-Manifest</code></td><td>The imported <code>manifests/assessments.psd1</code> hashtable (passed automatically by assessment mode).</td></tr></tbody></table><p>Returns an array of <code>[pscustomobject]</code> results (<code>Check</code>, <code>Ok</code>, <code>Fix</code>) — the ARM check&#39;s <code>Ok</code> is a live-validated <code>$true</code>/<code>$false</code>; the Graph checks&#39; <code>Ok</code> is always <code>$null</code> (informational, not live-verified). Full explanation: <a href="./../assessment/assessment-permissions.html#what-permissionaudit-actually-verifies">what <code>-PermissionAudit</code> actually verifies</a>.</p>`,36)])])}const p=t(r,[["render",s]]);export{m as __pageData,p as default};
